corrected_code:
@router.post("/proxy/downstream/service-call")
async def proxy_downstream_service(
    request: Request,
    payload: DownstreamProxyPayload,
    http_client: httpx.AsyncClient = Depends(get_async_http_client),
    current_user: User = Depends(get_current_user)
):
    if payload.target_user_id != str(current_user.id) and not current_user.is_service_admin:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized to impersonate target user in downstream baggage")

    ctx = baggage.set_baggage("user_id", str(current_user.id))
    carrier = {}
    TraceContextTextMapPropagator().inject(carrier, context=ctx)

    resp = await http_client.post(
        f"http://internal-user-service.mesh/api/v1/profiles/details",
        headers=carrier,
        json={"reason": payload.reason}
    )
    return resp.json()
